9	)
10	
11	// failedResubmitExpectations 汇总失败尝试发生前已保存事实，供 reopen 前后
12	// 用同一组期望核对。
13	type failedResubmitExpectations struct {
14		hID                        string
15		fromShift, toShift         string
16		idA, idB                   string
17		otherConfirmedAt           time.Time // 同交接中另一项已接收的处理时间
18		r1ReturnedAt               time.Time // 第一轮退回时间
19		r1ResubmitAt               time.Time // 第一轮成功重新提交时间
20		r2ReturnedAt               time.Time // 最近一轮（第二轮）退回时间
21		failAt                     time.Time // 失败尝试时刻（不应留下任何痕迹）
22		r1Reason, r1Supplement     string
23		r2Reason, failedSupplement string
24	}
