26	// assertStillReturnedAfterFailedResubmit 用当前打开的数据核对：保存失败后
27	// 事项仍是“退回、等待交班人补充”，失败前已保存的两轮退回与第一轮补充事实
28	// 原样保留，本次失败的补充不产生任何半完成结果；交接查询、事项处理经过与
29	// 展示层都与已保存事实一致。
30	func assertStillReturnedAfterFailedResubmit(t *testing.T, f *fixture, w failedResubmitExpectations) {
31		t.Helper()
32	
33		// 交接：整份交接继续未完成且没有完成时间；没有生成第二条交接。
34		h, err := f.svc.GetHandover(w.hID)
35		if err != nil {
36			t.Fatalf("get handover: %v", err)
37		}
38		if h.Completed() || h.CompletedAt != nil {
39			t.Fatalf("保存失败后整份交接应继续未完成、不能留下完成时间：%+v", h)
40		}
41		if hs := f.svc.ListHandovers(); len(hs) != 1 || hs[0].ID != w.hID {
42			t.Fatalf("失败尝试不应生成另一条交接：%+v", hs)
43		}
44	
45		e := findEntryOf(t, h, w.idA)
46	
47		// 当前结果仍为退回，继续等待交班人补充；原来保存的接班处理人（退回人）
48		// 与处理时间保持原样，不能提前清空或显示成尚未处理。
49		if e.Status != EntryReturned {
50			t.Fatalf("失败后当前结果应仍为退回，got %s", e.Status)
51		}
52		if e.Operator != "李四" || e.ProcessedAt == nil || !e.ProcessedAt.Equal(w.r2ReturnedAt) {
53			t.Fatalf("最近一轮退回的处理人与处理时间应保持原样：op=%s at=%v want 李四 %s",
54				e.Operator, e.ProcessedAt, w.r2ReturnedAt)
55		}
56	
57		// 最近一轮退回原因、退回人、退回时间和轮次保留；不出现本次尝试填写的
58		// 补充说明、补充人、补充时间或重新提交时间，也不多出一轮。
59		if len(e.Rounds) != 2 {
60			t.Fatalf("应仍为两轮退回记录，失败尝试不多出一轮，got %d：%+v", len(e.Rounds), e.Rounds)
61		}
62		r1, r2 := e.Rounds[0], e.Rounds[1]
63		if r1.Seq != 1 || r1.Reason != w.r1Reason || r1.ReturnOperator != "李四" ||
64			!r1.ReturnedAt.Equal(w.r1ReturnedAt) {
65			t.Fatalf("第一轮退回信息应保留：%+v", r1)
66		}
67		// 此前已经成功保存的第一轮补充不能丢失或被覆盖。
68		if r1.Supplement != w.r1Supplement || r1.SupplementOperator != "张三" ||
69			r1.SupplementAt == nil || !r1.SupplementAt.Equal(w.r1ResubmitAt) ||
70			r1.ResubmittedAt == nil || !r1.ResubmittedAt.Equal(w.r1ResubmitAt) {
71			t.Fatalf("第一轮补充与重新提交信息应原样保留：%+v", r1)
72		}
73		if r2.Seq != 2 || r2.Reason != w.r2Reason || r2.ReturnOperator != "李四" ||
74			!r2.ReturnedAt.Equal(w.r2ReturnedAt) {
75			t.Fatalf("最近一轮退回原因、退回人、退回时间应保留：%+v", r2)
76		}
77		if r2.Supplement != "" || r2.SupplementOperator != "" ||
78			r2.SupplementAt != nil || r2.ResubmittedAt != nil {
79			t.Fatalf("失败尝试不得写入补充说明、补充人、补充时间或重新提交时间：%+v", r2)
80		}
81	
82		// 同一份交接中另一项已经接收的结果、处理人和处理时间不受影响。
83		oe := findEntryOf(t, h, w.idB)
84		if oe.Status != EntryConfirmed || oe.Operator != "李四" ||
85			oe.ProcessedAt == nil || !oe.ProcessedAt.Equal(w.otherConfirmedAt) {
86			t.Fatalf("已接收的其他事项处理信息应保持原样：%+v", oe)
87		}
88	
89		// 事项继续留在交班班次，原文、严重程度、限制条件和后续负责人不因补充
90		// 失败而变化；不复制事项。
91		it, err := f.svc.GetItem(w.idA)
92		if err != nil {
93			t.Fatalf("get item: %v", err)
94		}
95		if it.CurrentShiftID != w.fromShift {
96			t.Fatalf("事项应继续留在交班班次 %s，got %s", w.fromShift, it.CurrentShiftID)
97		}
98		if len(it.ShiftIDs) != 1 || it.ShiftIDs[0] != w.fromShift {
99			t.Fatalf("事项流经班次不应变化：%v", it.ShiftIDs)
100		}
101		if it.Content != e.Content || it.Severity != e.Severity ||
102			it.Constraints != e.Constraints || it.FollowOwner != e.FollowOwner {
103			t.Fatalf("原文、严重程度、限制条件和后续负责人应与交接清单一致：item=%+v entry=%+v", it, e)
104		}
105		if it.Content != "事项甲" || it.FollowOwner != "李四" {
106			t.Fatalf("事项原文与后续负责人应保持原值：%+v", it)
107		}
108		if n := countItems(f, w.idA); n != 1 {
109			t.Fatalf("失败尝试不应复制事项，编号 %s 出现 %d 次", w.idA, n)
110		}
111	
112		// 处理经过查询呈现失败前的事实：当前结果为退回、等待补充；时间线只含
113		// 两轮退回与第一轮成功重新提交，不混入失败尝试的说明或时刻。
114		j, err := f.svc.ItemJourney(w.idA)
115		if err != nil {
116			t.Fatalf("journey: %v", err)
117		}
118		if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryReturned {
119			t.Fatalf("处理经过中的交接当前结果应仍为退回：%+v", j.Results)
120		}
121		if got := joinStrings(journeyKinds(j)); got != "created,handover-init,return,resubmit,return" {
122			t.Fatalf("处理经过应只保留失败前的两轮退回与第一轮重新提交，got %s", got)
123		}
124		resubmits, returns := 0, 0
125		for _, ev := range j.Events {
126			if ev.TimeKnown && ev.At.Equal(w.failAt) {
127				t.Fatalf("失败尝试时刻 %s 不应出现在处理经过：%+v", w.failAt, ev)
128			}
129			if strings.Contains(ev.Supplement, w.failedSupplement) ||
130				strings.Contains(ev.Detail, w.failedSupplement) {
131				t.Fatalf("失败尝试的补充说明不应出现在处理经过：%+v", ev)
132			}
133			switch ev.Kind {
134			case "return":
135				returns++
136			case "resubmit":
137				resubmits++
138				if ev.RoundSeq != 1 || ev.Supplement != w.r1Supplement ||
139					ev.SupplementOperator != "张三" || ev.SupplementAt == nil ||
140					!ev.SupplementAt.Equal(w.r1ResubmitAt) {
141					t.Fatalf("唯一的重新提交应是第一轮已成功保存的那次：%+v", ev)
142				}
143			case "confirm", "track", "received":
144				t.Fatalf("失败尝试不应被当成提交成功或接收：%+v", ev)
145			}
146		}
147		if returns != 2 || resubmits != 1 {
148			t.Fatalf("应只有两次退回、一次（第一轮）重新提交，got returns=%d resubmits=%d",
149				returns, resubmits)
150		}
151		jText := FormatItemJourney(j)
152		if !strings.Contains(jText, "退回（等待交班人补充）") {
153			t.Fatalf("处理经过应显示退回、等待交班人补充：\n%s", jText)
154		}
155		if strings.Contains(jText, "第2次重新提交") || strings.Contains(jText, w.failedSupplement) {
156			t.Fatalf("处理经过不应出现第二轮重新提交或失败尝试的说明：\n%s", jText)
157		}
158	
159		// 交接展示与保存事实一致：未完成、退回项保留退回人与退回时间、两轮记录
160		// 中只有第一轮带补充，不出现失败尝试的补充与重新提交时刻。
161		text := FormatHandover(h)
162		if !strings.Contains(text, "[未完成]") {
163			t.Fatalf("交接应显示未完成：\n%s", text)
164		}
165		if !strings.Contains(text, "[退回]") {
166			t.Fatalf("事项应显示退回状态：\n%s", text)
167		}
168		if !strings.Contains(text, "最后处理：处理人=李四；处理时间="+fmtTime(w.r2ReturnedAt)) {
169			t.Fatalf("退回项应显示原来的退回人与退回时间，不能显示尚未处理：\n%s", text)
170		}
171		if !strings.Contains(text, "第1次退回") || !strings.Contains(text, w.r1Supplement) ||
172			!strings.Contains(text, "第2次退回") || !strings.Contains(text, w.r2Reason) {
173			t.Fatalf("两轮退回原因与第一轮补充都应保留：\n%s", text)
174		}
175		if strings.Contains(text, w.failedSupplement) ||
176			strings.Contains(text, "已重新提交："+fmtTime(w.failAt)) {
177			t.Fatalf("失败尝试的补充说明与重新提交时间不应出现在交接查询中：\n%s", text)
178		}
179	
180		// 交班班次结束时记录保留原来的内容与负责人。
181		rep, err := f.svc.ShiftReport(w.fromShift)
182		if err != nil {
183			t.Fatalf("report from shift: %v", err)
184		}
185		snap := findCloseItem(rep, w.idA)
186		if snap == nil || snap.Content != "事项甲" || snap.FollowOwner != "李四" {
187			t.Fatalf("交班班次结束时记录应保持原内容与负责人：%+v", snap)
188		}
189	
190		// 退回项仍等待补充，接班班次不能结束。
191		if _, err := f.svc.CloseShift(w.toShift); !errors.Is(err, ErrHandoverState) {
192			t.Fatalf("退回项未补充完成时接班班次不能结束，got %v", err)
193		}
194	}
