207	// TestResubmitSaveFailureAtomicRollback：交班人对已经历一轮退回与补充、后来
208	// 又被再次退回的事项，在原交接记录上填写操作人与非空补充说明并重新提交，
209	// 业务条件全部成立、真正进入保存过程后本地写盘失败——操作必须明确返回保存
210	// 错误，不能当成提交成功；内存与磁盘都回到失败前：当前结果仍为退回并保留
211	// 最近一轮退回人/时间，两轮退回与第一轮补充完整，不出现本次补充、补充人、
212	// 补充时间、重新提交时间，也不多出一轮；同交接已接收的另一项与整份交接的
213	// 未完成状态不变。缺少必填内容、编号不存在或状态不允许的业务拒绝都不能代替
214	// 这个场景。保存恢复后在原交接记录上对同一退回项补充并重新提交成功，处理
215	// 经过只留下成功的这次，随后接班人按原规则接收，交接才完成。
216	func TestResubmitSaveFailureAtomicRollback(t *testing.T) {
217		f := newFixture(t)
218		a, b, items := prepareHandover(t, f)
219		h, err := f.svc.CreateHandover(a.ID, b.ID)
220		if err != nil {
221			t.Fatalf("create handover: %v", err)
222		}
223		idA, idB := items[0].ID, items[1].ID // 事项甲、事项乙（事项丙已关闭）
224	
225		// 同交接另一项先成功接收，后续核对它不受失败尝试影响。
226		otherConfirmedAt := tsDay(2, 16, 30)
227		f.svc.nowAt(func() time.Time { return otherConfirmedAt })
228		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
229			t.Fatalf("confirm other: %v", err)
230		}
231	
232		// 第一轮：退回 -> 交班人补充并重新提交。
233		r1ReturnedAt := tsDay(2, 17, 0)
234		f.svc.nowAt(func() time.Time { return r1ReturnedAt })
235		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "第一轮原因", "", ""); err != nil {
236			t.Fatalf("return round 1: %v", err)
237		}
238		r1ResubmitAt := tsDay(2, 17, 30)
239		f.svc.nowAt(func() time.Time { return r1ResubmitAt })
240		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "第一轮补充内容"); err != nil {
241			t.Fatalf("resubmit round 1: %v", err)
242		}
243	
244		// 后来又被再次退回：产生第二轮并重新等待补充。
245		r2ReturnedAt := tsDay(2, 18, 0)
246		f.svc.nowAt(func() time.Time { return r2ReturnedAt })
247		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "第二轮原因", "", ""); err != nil {
248			t.Fatalf("return round 2: %v", err)
249		}
250		pre, _ := f.svc.GetHandover(h.ID)
251		preEntry := findEntryOf(t, pre, idA)
252		if preEntry.Status != EntryReturned || len(preEntry.Rounds) != 2 {
253			t.Fatalf("前置：事项应处于第二轮退回状态，got %+v", preEntry)
254		}
255	
256		want := failedResubmitExpectations{
257			hID: h.ID, fromShift: a.ID, toShift: b.ID, idA: idA, idB: idB,
258			otherConfirmedAt: otherConfirmedAt,
259			r1ReturnedAt:     r1ReturnedAt, r1ResubmitAt: r1ResubmitAt,
260			r2ReturnedAt: r2ReturnedAt,
261			failAt:       tsDay(2, 18, 30),
262			r1Reason:     "第一轮原因", r1Supplement: "第一轮补充内容",
263			r2Reason: "第二轮原因", failedSupplement: "第二轮补充-失败尝试",
264		}
265	
266		// 记录失败前已落盘的文件内容，并固定失败尝试的时刻。
267		rawBefore, err := os.ReadFile(f.store.Path())
268		if err != nil {
269			t.Fatalf("read data file: %v", err)
270		}
271		f.svc.nowAt(func() time.Time { return want.failAt })
272	
273		// 操作人与非空补充都已填写、编号存在、事项正处于允许重新提交的退回
274		// 状态；使下一次写盘在原子保存阶段失败。
275		breakSaving(t, f)
276		_, err = f.svc.ResubmitReturned(h.ID, idA, "张三", want.failedSupplement)
277		if err == nil {
278			t.Fatalf("保存失败时重新提交应明确返回错误，不能当成提交成功")
279		}
280		if !strings.Contains(err.Error(), "写入数据文件失败") {
281			t.Fatalf("应明确返回保存阶段的错误，got %v", err)
282		}
283		// 业务条件全部成立，不能用缺少必填内容、编号不存在或状态不允许的拒绝
284		// 来冒充这个保存失败场景。
285		if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrHandoverState) || errors.Is(err, ErrNotFound) {
286			t.Fatalf("参数合法、状态允许时的保存失败不应被报告为业务校验错误，got %v", err)
287		}
288	
289		// 当前打开的数据上查看交接与处理经过，应看到失败前的事实，而不是只保证
290		// 文件没变、查询却显示已经提交。
291		assertStillReturnedAfterFailedResubmit(t, f, want)
292	
293		// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
294		rawAfter, err := os.ReadFile(f.store.Path())
295		if err != nil {
296			t.Fatalf("read data file after failure: %v", err)
297		}
298		if string(rawAfter) != string(rawBefore) {
299			t.Fatalf("保存失败不得改动既有数据文件")
300		}
301	
302		// 退出后重新打开：退回状态、两轮记录与已接收的另一项全部与失败前一致，
303		// 失败尝试不产生重新提交经过。
304		f.reopen(t)
305		assertStillReturnedAfterFailedResubmit(t, f, want)
306	
307		// 保存恢复正常后，交班人仍能在原交接记录上对同一退回项补充并重新提交。
308		restoreSaving(t, f)
309		successAt := tsDay(2, 19, 0)
310		f.svc.nowAt(func() time.Time { return successAt })
311		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "第二轮补充-成功提交"); err != nil {
312			t.Fatalf("恢复后重新提交应成功：%v", err)
313		}
314	
315		// 这次成功仅让该项恢复待处理：当前处理人和处理时间显示尚未处理。
316		h2, err := f.svc.GetHandover(h.ID)
317		if err != nil {
318			t.Fatalf("get handover after retry: %v", err)
319		}
320		if h2.Completed() || h2.CompletedAt != nil {
321			t.Fatalf("重新提交不等于接收，交接应继续未完成：%+v", h2)
322		}
323		le := findEntryOf(t, h2, idA)
324		if le.Status != EntryPending || le.Operator != "" || le.ProcessedAt != nil {
325			t.Fatalf("成功重新提交后应恢复待处理、当前处理人与处理时间为尚未处理：%+v", le)
326		}
327		if len(le.Rounds) != 2 {
328			t.Fatalf("轮次不应增加，got %d", len(le.Rounds))
329		}
330		// 新的补充写在最近一轮（第二轮），记录成功提交时的补充人、补充时间与
331		// 重新提交时间；原退回信息及第一轮内容继续保留。
332		s1, s2 := le.Rounds[0], le.Rounds[1]
333		if s1.Reason != want.r1Reason || s1.Supplement != want.r1Supplement ||
334			s1.SupplementOperator != "张三" || s1.SupplementAt == nil ||
335			!s1.SupplementAt.Equal(want.r1ResubmitAt) {
336			t.Fatalf("第一轮退回与补充应继续保留：%+v", s1)
337		}
338		if s2.Reason != want.r2Reason || s2.ReturnOperator != "李四" ||
339			!s2.ReturnedAt.Equal(want.r2ReturnedAt) {
340			t.Fatalf("第二轮原退回信息应保留：%+v", s2)
341		}
342		if s2.Supplement != "第二轮补充-成功提交" || s2.SupplementOperator != "张三" ||
343			s2.SupplementAt == nil || !s2.SupplementAt.Equal(successAt) ||
344			s2.ResubmittedAt == nil || !s2.ResubmittedAt.Equal(successAt) {
345			t.Fatalf("第二轮应记录成功提交的补充人、补充时间与重新提交时间：%+v", s2)
346		}
347	
348		// 事项仍留在交班班次，原文、严重程度、限制条件和后续负责人不变。
349		it, err := f.svc.GetItem(idA)
350		if err != nil {
351			t.Fatalf("get item after retry: %v", err)
352		}
353		if it.CurrentShiftID != a.ID || len(it.ShiftIDs) != 1 || it.ShiftIDs[0] != a.ID {
354			t.Fatalf("重新提交不移动事项：%+v", it)
355		}
356		if it.Content != "事项甲" || it.FollowOwner != "李四" {
357			t.Fatalf("事项原文与后续负责人应不变：%+v", it)
358		}
359	
360		// 处理经过只呈现成功的这次第二轮重新提交，不混入失败尝试的说明或时刻；
361		// 第一轮经过仍在。
362		j, err := f.svc.ItemJourney(idA)
363		if err != nil {
364			t.Fatalf("journey after retry: %v", err)
365		}
366		if got := joinStrings(journeyKinds(j)); got != "created,handover-init,return,resubmit,return,resubmit" {
367			t.Fatalf("处理经过应呈现两轮退回与两次成功重新提交，got %s", got)
368		}
369		if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryPending {
370			t.Fatalf("交接当前结果应显示待处理：%+v", j.Results)
371		}
372		secondResubmits := 0
373		for _, ev := range j.Events {
374			if strings.Contains(ev.Supplement, want.failedSupplement) ||
375				(ev.TimeKnown && ev.At.Equal(want.failAt)) {
376				t.Fatalf("处理经过不能混入失败尝试的说明或时刻：%+v", ev)
377			}
378			if ev.Kind == "resubmit" && ev.RoundSeq == 2 {
379				secondResubmits++
380				if !ev.TimeKnown || !ev.At.Equal(successAt) || ev.Operator != "张三" ||
381					ev.Supplement != "第二轮补充-成功提交" || ev.SupplementAt == nil ||
382					!ev.SupplementAt.Equal(successAt) {
383					t.Fatalf("第二轮重新提交应只反映成功操作：%+v", ev)
384				}
385			}
386		}
387		if secondResubmits != 1 {
388			t.Fatalf("第二轮应只有一次（成功的）重新提交，got %d", secondResubmits)
389		}
390		jText := FormatItemJourney(j)
391		if !strings.Contains(jText, "待处理（接班人尚未处理）") {
392			t.Fatalf("处理经过当前结果应显示待处理、接班人尚未处理：\n%s", jText)
393		}
394		if strings.Contains(jText, want.failedSupplement) {
395			t.Fatalf("失败尝试的说明不能混入成功后的处理经过：\n%s", jText)
396		}
397	
398		// 保留现有接班人之后逐项处理的规则：确认接收后事项才进入接班班次，
399		// 整份交接在这一刻才完成，完成时间以本次成功处理为准。
400		confirmAt := tsDay(2, 19, 30)
401		f.svc.nowAt(func() time.Time { return confirmAt })
402		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
403			t.Fatalf("重新提交后接班人确认应成功：%v", err)
404		}
405		h3, err := f.svc.GetHandover(h.ID)
406		if err != nil {
407			t.Fatalf("get handover after confirm: %v", err)
408		}
409		if !h3.Completed() || h3.CompletedAt == nil || !h3.CompletedAt.Equal(confirmAt) {
410			t.Fatalf("全部接收后交接才完成，完成时间应以确认时刻为准：%+v", h3)
411		}
412		ce := findEntryOf(t, h3, idA)
413		if ce.Status != EntryConfirmed || ce.Operator != "李四" ||
414			ce.ProcessedAt == nil || !ce.ProcessedAt.Equal(confirmAt) {
415			t.Fatalf("事项应记录本次确认接收：%+v", ce)
416		}
417		if len(ce.Rounds) != 2 || ce.Rounds[1].Supplement != "第二轮补充-成功提交" {
418			t.Fatalf("两轮退回与成功补充应作为历史保留：%+v", ce.Rounds)
419		}
420		it2, err := f.svc.GetItem(idA)
421		if err != nil {
422			t.Fatalf("get item after confirm: %v", err)
423		}
424		if it2.CurrentShiftID != b.ID || len(it2.ShiftIDs) != 2 {
425			t.Fatalf("确认接收后事项才进入接班班次：%+v", it2)
426		}
427	
428		// 退出重开后，成功的重新提交与接收结果完整保留，失败尝试仍无痕迹。
429		f.reopen(t)
430		h4, err := f.svc.GetHandover(h.ID)
431		if err != nil {
432			t.Fatalf("reopen get handover: %v", err)
433		}
434		if !h4.Completed() || h4.CompletedAt == nil || !h4.CompletedAt.Equal(confirmAt) {
435			t.Fatalf("重开后交接完成状态与完成时间应保留：%+v", h4)
436		}
437		re := findEntryOf(t, h4, idA)
438		if re.Status != EntryConfirmed || len(re.Rounds) != 2 ||
439			re.Rounds[1].Supplement != "第二轮补充-成功提交" {
440			t.Fatalf("重开后第二轮成功补充应保留：%+v", re)
441		}
442		j4, err := f.svc.ItemJourney(idA)
443		if err != nil {
444			t.Fatalf("reopen journey: %v", err)
445		}
446		if got := joinStrings(journeyKinds(j4)); got != "created,handover-init,return,resubmit,return,resubmit,confirm" {
447			t.Fatalf("重开后处理经过应只保留成功的两次重新提交与确认接收，got %s", got)
448		}
449		for _, ev := range j4.Events {
450			if strings.Contains(ev.Supplement, want.failedSupplement) {
451				t.Fatalf("重开后失败尝试的说明仍不应出现：%+v", ev)
452			}
453		}
454	}
455

