1	package handover
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// failedCloseExpectations 汇总结束失败尝试发生前已保存的业务事实，供 reopen
13	// 前后用同一组期望核对，以及成功结束后对照。
14	type failedCloseExpectations struct {
15		aID, bID, hID           string
16		idOpen, idNew, idClosed string
17		aClosedAt               time.Time // 上一班成功结束的时间（其结束时记录不受影响）
18		idClosedAt              time.Time // 上一班已关闭事项的关闭时间
19		handoverCreatedAt       time.Time
20		trackAt                 time.Time // 唯一交接事项成功接收（继续跟踪）的时间
21		openUpdatedAt           time.Time // 接班后第一次修改未关闭事项的时间
22		idNewClosedAt           time.Time // 本班新增事项的关闭时间
23		failAt                  time.Time // 失败的结束尝试时刻（不应留下任何痕迹）
24		reUpdateAt              time.Time // 保存恢复后再次修改未关闭事项的时间
25		successAt               time.Time // 真正成功结束本班的时间
26		origContent             string
27		origConstraints         string
28		trackNote               string
29		trackFollow             string // 接收当时指定的后续负责人（交接记录保存）
30		midContent              string
31		midConstraints          string
32		midFollow               string
33		midSeverity             Severity
34		finalContent            string
35		finalConstraints        string
36		finalFollow             string
37		finalSeverity           Severity
38	}
39	
40	// assertStillOpenAfterFailedClose 用当前打开的数据核对：保存失败后本班仍在
41	// 进行中，没有结束时间，也没有结束时事项记录；失败前已保存的事项、交接与
42	// 上一班结束时记录全部原样保留，本次失败不成为任何业务事实。
43	func assertStillOpenAfterFailedClose(t *testing.T, f *fixture, w failedCloseExpectations) {
44		t.Helper()
45	
46		// 失败尝试不新增班次或交接，也不复制事项。
47		if hs := f.svc.ListShifts(); len(hs) != 2 {
48			t.Fatalf("失败尝试不应新增班次，got %d 个：%+v", len(hs), hs)
49		}
50		if hs := f.svc.ListHandovers(); len(hs) != 1 || hs[0].ID != w.hID {
51			t.Fatalf("失败尝试不应新增交接：%+v", hs)
52		}
