252	// assertClosedWithSuccessRecord 用当前打开的数据核对：保存恢复后本班成功
253	// 结束，结束时间与结束时记录都只属于这次成功操作；失败尝试无痕迹。
254	func assertClosedWithSuccessRecord(t *testing.T, f *fixture, w failedCloseExpectations) {
255		t.Helper()
256	
257		b, err := f.svc.GetShift(w.bID)
258		if err != nil {
259			t.Fatalf("get shift after success: %v", err)
260		}
261		if !b.Closed || b.ClosedAt == nil || !b.ClosedAt.Equal(w.successAt) || b.CloseRecord == nil {
262			t.Fatalf("本班应以成功操作时刻结束并留下结束时记录：%+v", b)
263		}
264	
265		repB, err := f.svc.ShiftReport(w.bID)
266		if err != nil {
267			t.Fatalf("report b after success: %v", err)
268		}
269		if !repB.ItemsAtClose || repB.HistoryIncomplete {
270			t.Fatalf("成功结束后事项区应标为结束时记录：%+v", repB)
271		}
272		// 结束时记录含本班新增且已关闭的事项与已经接收但未关闭的事项，每项一次。
273		if len(repB.CloseItems) != 2 {
274			t.Fatalf("结束时记录应含2项，got %d", len(repB.CloseItems))
275		}
276		if repB.CloseItems[0].ItemID != w.idOpen || repB.CloseItems[1].ItemID != w.idNew {
277			t.Fatalf("结束时记录应按编号排列、每项一次：%s %s",
278				repB.CloseItems[0].ItemID, repB.CloseItems[1].ItemID)
279		}
280		// 未关闭事项按成功时的信息冻结，保留再次修改后的内容、严重程度、限制条件
281		// 与负责人，结束时仍未关闭。
282		so := findCloseItem(repB, w.idOpen)
283		if so == nil || so.Content != w.finalContent || so.Severity != w.finalSeverity ||
284			so.Constraints != w.finalConstraints || so.FollowOwner != w.finalFollow || so.Closed ||
285			so.CloseOperator != "" || so.ClosedAt != nil {
286			t.Fatalf("未关闭事项应以成功时的信息冻结且仍为未关闭：%+v", so)
287		}
288		// 已关闭事项保留原关闭人与关闭时间，不被重新打开。
289		sn := findCloseItem(repB, w.idNew)
290		if sn == nil || !sn.Closed || sn.CloseOperator != "李四" ||
291			sn.ClosedAt == nil || !sn.ClosedAt.Equal(w.idNewClosedAt) {
292			t.Fatalf("已关闭事项应保留原关闭人与关闭时间：%+v", sn)
293		}
294		// 上一班已关闭事项不属于本班结束时记录。
295		if findCloseItem(repB, w.idClosed) != nil {
296			t.Fatalf("上一班已关闭事项不应出现在本班结束时记录中")
297		}
298		latest := repB.LatestItems[w.idOpen]
299		if latest.CurrentShiftID != w.bID || latest.FollowOwner != w.finalFollow || latest.Closed {
300			t.Fatalf("最新状态对照应反映成功时的未关闭事项：%+v", latest)
301		}
302	
303		textB := FormatReport(repB)
304		if !strings.Contains(textB, "以下为结束时记录") ||
305			!strings.Contains(textB, w.finalContent) ||
306			!strings.Contains(textB, "结束时后续负责人："+w.finalFollow) {
307			t.Fatalf("本班报告应按成功时信息展示结束时记录：\n%s", textB)
308		}
309		if !strings.Contains(textB, fmt.Sprintf("结束时已关闭（李四 于 %s）", fmtTime(w.idNewClosedAt))) {
310			t.Fatalf("本班结束时记录应保留已关闭项的关闭人与关闭时间：\n%s", textB)
311		}
312		if strings.Contains(textB, fmtTime(w.failAt)) || strings.Contains(textB, w.midContent) {
313			t.Fatalf("失败尝试时刻与失败前的中间值不应进入成功后的结束时记录：\n%s", textB)
314		}
315	
316		// 上一班仍展示它自己的原始结束时记录，不随后班修改或成功结束改变。
317		repA, err := f.svc.ShiftReport(w.aID)
318		if err != nil {
319			t.Fatalf("report a after success: %v", err)
320		}
