324		}
325		sc := findCloseItem(repA, w.idClosed)
326		if sc == nil || !sc.Closed || sc.CloseOperator != "张三" {
327			t.Fatalf("上一班已关闭事项记录应保留：%+v", sc)
328		}
329		textA := FormatReport(repA)
330		if !strings.Contains(textA, "以下为结束时记录") || !strings.Contains(textA, w.origContent) {
331			t.Fatalf("上一班报告应仍展示自己的原始结束时记录：\n%s", textA)
332		}
333	
334		// 既有交接仍是原来的接收结果；交接记录中继续跟踪当时的负责人不被后来的
335		// 修改覆盖。
336		h, err := f.svc.GetHandover(w.hID)
337		if err != nil {
338			t.Fatalf("get handover after success: %v", err)
339		}
