342		}
343		e := findEntryOf(t, h, w.idOpen)
344		if e.Status != EntryTracking || e.Operator != "李四" ||
345			e.ProcessedAt == nil || !e.ProcessedAt.Equal(w.trackAt) ||
346			e.TrackingNote != w.trackNote || e.FollowOwner != w.trackFollow {
347			t.Fatalf("交接接收记录应保留接收当时保存的信息：%+v", e)
348		}
349	
350		// 未关闭事项本身：仍未关闭、保留编号与流经班次，处理经过只留下成功的
351		// 业务事实（一次接收、两次修改），没有失败尝试时刻。
352		it, err := f.svc.GetItem(w.idOpen)
353		if err != nil {
354			t.Fatalf("get item after success: %v", err)
355		}
356		if it.Closed || it.Content != w.finalContent || it.Severity != w.finalSeverity ||
357			it.Constraints != w.finalConstraints || it.FollowOwner != w.finalFollow {
358			t.Fatalf("未关闭事项应保持成功时的当前信息：%+v", it)
359		}
360		if it.OriginShiftID != w.aID || it.CurrentShiftID != w.bID ||
361			len(it.ShiftIDs) != 2 || it.ShiftIDs[0] != w.aID || it.ShiftIDs[1] != w.bID {
362			t.Fatalf("事项编号与流经班次应保持：%+v", it)
363		}
364		// 事项自身历史：只发生过一次接收、两次成功修改；没有失败尝试的任何痕迹。
365		kinds := make([]string, 0, len(it.Events))
366		received := 0
367		for _, ev := range it.Events {
368			kinds = append(kinds, ev.Kind)
369			if ev.Kind == "received" {
370				received++
371			}
372			if !ev.At.IsZero() && ev.At.Equal(w.failAt) {
373				t.Fatalf("失败尝试时刻不应出现在事项历史：%+v", ev)
374			}
375		}
376		if received != 1 || joinStrings(kinds) != "created,received,updated,updated" {
377			t.Fatalf("事项历史应只留下一次接收与两次成功修改，got %v", kinds)
378		}
379		j, err := f.svc.ItemJourney(w.idOpen)
380		if err != nil {
381			t.Fatalf("journey after success: %v", err)
382		}
383		if got := joinStrings(journeyKinds(j)); got != "created,handover-init,track,updated,updated" {
384			t.Fatalf("处理经过应呈现一次接收与两次成功修改，got %s", got)
385		}
386		updatedAt := []time.Time{}
387		for _, ev := range j.Events {
388			if ev.TimeKnown && ev.At.Equal(w.failAt) {
389				t.Fatalf("失败尝试时刻不应出现在成功后的处理经过：%+v", ev)
390			}
391			if ev.Kind == "updated" {
392				updatedAt = append(updatedAt, ev.At)
393			}
394		}
395		if len(updatedAt) != 2 ||
396			!updatedAt[0].Equal(w.openUpdatedAt) || !updatedAt[1].Equal(w.reUpdateAt) {
397			t.Fatalf("两次修改应分别为接班后与保存恢复后的成功修改：%v", updatedAt)
398		}
399	
400		// 已结束班次不能重复结束。
401		if _, err := f.svc.CloseShift(w.bID); !errors.Is(err, ErrShiftClosed) {
402			t.Fatalf("成功结束后重复结束应报错，got %v", err)
403		}
404	}
405	
406	// TestCloseShiftSaveFailureAtomicRollback：编号正确、班次仍在进行中、接班
407	// 交接已全部明确接收、本班又存在已关闭与未关闭事项时结束班次，业务条件全部
408	// 成立、真正进入保存过程后本地写盘失败——结束操作必须明确返回保存错误，
409	// 不能当成结束成功；内存与磁盘都回到失败前：班次仍进行中、无结束时间、无
410	// 本次生成的结束时事项记录，事项区仍展示当前信息；未关闭事项保持接班后
411	// 修改的内容/严重程度/限制条件/负责人且不退回上一班，已关闭事项不被重新
412	// 打开；既有交接的接收结果、处理人、处理时间与完成时间保留，上一班的
413	// 结束时记录不受影响，原数据文件内容一个字节不变。保存恢复后仍能在同一
414	// 会话中修改本班未关闭事项并正常结束：结束时间属于这次成功操作，结束时
415	// 记录按成功时信息保存（含本班新增已关闭项与已接收未关闭项，每项一次；
416	// 已关闭项保留原关闭人与关闭时间），班次报告此时才标为结束时记录，上一班
417	// 仍展示自己的原始记录。
418	func TestCloseShiftSaveFailureAtomicRollback(t *testing.T) {
419		f := newFixture(t)
420		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
421		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
422	
423		// 上一班：一项未关闭（随后交给本班），一项结束前已关闭。
424		idOpen, err := f.svc.AddItem(a.ID, "上一班遗留的压力异常", SeverityNormal, "", "李四")
425		if err != nil {
426			t.Fatalf("add open item: %v", err)
427		}
428		idClosed, err := f.svc.AddItem(a.ID, "上一班已关闭的巡检事项", SeverityImportant, "需复查记录", "李四")
429		if err != nil {
430			t.Fatalf("add closed item: %v", err)
431		}
432		itemClosedAt := tsDay(2, 14, 0)
433		f.svc.nowAt(func() time.Time { return itemClosedAt })
434		if _, err := f.svc.CloseItem(idClosed.ID, "张三"); err != nil {
435			t.Fatalf("close item in prior shift: %v", err)
436		}
437		aClosedAt := tsDay(2, 15, 0)
438		f.svc.nowAt(func() time.Time { return aClosedAt })
439		if _, err := f.svc.CloseShift(a.ID); err != nil {
440			t.Fatalf("close prior shift: %v", err)
441		}
442	
443		// 交接完成：唯一事项由接班人继续跟踪，明确接收并指定跟踪说明与新负责人。
444		handoverCreatedAt := tsDay(2, 16, 30)
445		f.svc.nowAt(func() time.Time { return handoverCreatedAt })
446		h, err := f.svc.CreateHandover(a.ID, b.ID)
447		if err != nil {
448			t.Fatalf("create handover: %v", err)
449		}
450		trackAt := tsDay(2, 17, 30)
451		f.svc.nowAt(func() time.Time { return trackAt })
452		if _, err := f.svc.ProcessEntry(h.ID, idOpen.ID, ActionTrack, "李四", "",
453			"持续跟踪压力变化", "王五"); err != nil {
454			t.Fatalf("track: %v", err)
455		}
456	
457		// 接班后修改过未关闭事项的内容、严重程度、限制条件和后续负责人，因此
458		// 两班保存的信息有所不同。
459		openUpdatedAt := tsDay(2, 18, 0)
460		f.svc.nowAt(func() time.Time { return openUpdatedAt })
461		if _, err := f.svc.UpdateItem(idOpen.ID, "接班后修订的压力异常", SeverityUrgent,
462			"接班后新增限制", "赵六"); err != nil {
463			t.Fatalf("update received item: %v", err)
464		}
465	
466		// 本班新增一项，并在结束尝试前关闭，关闭人与关闭时间已保存。
467		f.svc.nowAt(func() time.Time { return tsDay(2, 18, 30) })
468		idNew, err := f.svc.AddItem(b.ID, "本班新增的记录归档", SeverityNormal, "", "李四")
469		if err != nil {
470			t.Fatalf("add item in current shift: %v", err)
471		}
472		idNewClosedAt := tsDay(2, 19, 0)
473		f.svc.nowAt(func() time.Time { return idNewClosedAt })
474		if _, err := f.svc.CloseItem(idNew.ID, "李四"); err != nil {
475			t.Fatalf("close new item: %v", err)
476		}
477	
478		// 前置：交接已全部明确接收，编号正确、班次进行中——结束的业务条件成立。
479		got, _ := f.svc.GetHandover(h.ID)
480		if !got.Completed() {
481			t.Fatalf("前置：交接应已全部明确接收")
482		}
483		if pre, _ := f.svc.GetShift(b.ID); pre.Closed {
484			t.Fatalf("前置：本班应仍在进行中")
485		}
486	
487		want := failedCloseExpectations{
488			aID: a.ID, bID: b.ID, hID: h.ID,
489			idOpen: idOpen.ID, idNew: idNew.ID, idClosed: idClosed.ID,
490			aClosedAt:         aClosedAt,
491			idClosedAt:        itemClosedAt,
492			handoverCreatedAt: handoverCreatedAt,
493			trackAt:           trackAt,
494			openUpdatedAt:     openUpdatedAt,
495			idNewClosedAt:     idNewClosedAt,
496			failAt:            tsDay(2, 20, 0),
497			reUpdateAt:        tsDay(2, 21, 0),
498			successAt:         tsDay(2, 22, 0),
499			origContent:       "上一班遗留的压力异常",
500			origConstraints:   "",
501			trackNote:         "持续跟踪压力变化",
502			trackFollow:       "王五",
503			midContent:        "接班后修订的压力异常",
504			midConstraints:    "接班后新增限制",
505			midFollow:         "赵六",
506			midSeverity:       SeverityUrgent,
507			finalContent:      "再次修订的压力异常",
508			finalConstraints:  "最终限制条件",
509			finalFollow:       "钱七",
510			finalSeverity:     SeverityImportant,
511		}
512	
513		// 记录失败前已落盘的文件内容，并固定失败尝试的结束时刻。
514		rawBefore, err := os.ReadFile(f.store.Path())
515		if err != nil {
516			t.Fatalf("read data file: %v", err)
517		}
518		f.svc.nowAt(func() time.Time { return want.failAt })
519	
520		// 使下一次写盘在原子保存阶段失败。
521		breakSaving(t, f)
522		_, err = f.svc.CloseShift(b.ID)
523		if err == nil {
524			t.Fatalf("保存失败时结束班次应明确返回错误，不能当成结束成功")
525		}
526		if !strings.Contains(err.Error(), "写入数据文件失败") {
527			t.Fatalf("应明确返回保存阶段的错误，got %v", err)
528		}
529		// 业务条件全部成立，不能用编号不存在、班次已结束或接班交接未完成的拒绝
530		// 来冒充这个保存失败场景。
531		if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrHandoverState) ||
532			errors.Is(err, ErrNotFound) || errors.Is(err, ErrShiftClosed) {
533			t.Fatalf("编号正确、进行中且交接已接收时的保存失败不应被报告为业务校验错误，got %v", err)
534		}
535	
536		// 当前打开的数据上查看班次、事项、交接与报告，应看到失败前的事实，而不是
537		// 只保证文件没变、查询却显示已经结束。
538		assertStillOpenAfterFailedClose(t, f, want)
539	
540		// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
541		rawAfter, err := os.ReadFile(f.store.Path())
542		if err != nil {
543			t.Fatalf("read data file after failure: %v", err)
544		}
545		if string(rawAfter) != string(rawBefore) {
546			t.Fatalf("保存失败不得改动既有数据文件，失败的结束尝试不能成为其中的业务事实")
547		}
548	
549		// 退出后重新打开：班次进行中、事项与交接事实与失败前一致，仍无结束时记录。
550		f.reopen(t)
551		assertStillOpenAfterFailedClose(t, f, want)
552	
553		// 保存条件恢复后，用户仍能在同一应用中修改本班未关闭事项，再正常结束本班。
554		restoreSaving(t, f)
555		f.svc.nowAt(func() time.Time { return want.reUpdateAt })
556		if _, err := f.svc.UpdateItem(idOpen.ID, want.finalContent, want.finalSeverity,
557			want.finalConstraints, want.finalFollow); err != nil {
558			t.Fatalf("恢复后应仍能修改本班未关闭事项：%v", err)
559		}
560		retry, _ := f.svc.GetItem(idOpen.ID)
561		if retry.Content != want.finalContent || retry.Severity != want.finalSeverity ||
562			retry.Constraints != want.finalConstraints || retry.FollowOwner != want.finalFollow ||
563			retry.Closed || retry.CurrentShiftID != b.ID {
564			t.Fatalf("恢复后修改应已生效且事项仍未关闭、仍在本班：%+v", retry)
565		}
566		f.svc.nowAt(func() time.Time { return want.successAt })
567		if _, err := f.svc.CloseShift(b.ID); err != nil {
568			t.Fatalf("保存恢复后结束班次应成功：%v", err)
569		}
570	
571		// 成功后的结束时间属于这次成功操作，结束时记录按成功时的事项信息保存。
572		assertClosedWithSuccessRecord(t, f, want)
573	
574		// 成功落盘的文件只包含成功事实，不包含失败尝试时刻。
575		rawSuccess, err := os.ReadFile(f.store.Path())
576		if err != nil {
577			t.Fatalf("read data file after success: %v", err)
578		}
579		if !strings.Contains(string(rawSuccess), want.successAt.Format("2006-01-02T15:04:05-07:00")) {
580			t.Fatalf("成功结束时间应已写入数据文件")
581		}
582		if strings.Contains(string(rawSuccess), want.failAt.Format("2006-01-02T15:04:05-07:00")) {
583			t.Fatalf("失败的结束尝试时刻不应留在数据文件中")
584		}
585	
586		// 退出重开后，成功结束的事实与上一班原始记录都完整保留，失败尝试仍无痕迹。
587		f.reopen(t)
588		assertClosedWithSuccessRecord(t, f, want)
589	}
590

