1331			t.Fatalf("return: %v", err)
1332		}
1333		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
1334			t.Fatalf("confirm idB: %v", err)
1335		}
1336	
1337		before, _ := f.svc.GetHandover(h.ID)
1338		eaBefore := findEntryOf(t, before, idA)
1339		returnedAt := eaBefore.ProcessedAt
1340		if eaBefore.Status != EntryReturned || len(eaBefore.Rounds) != 1 {
1341			t.Fatalf("前置状态应为退回且只有1轮：%+v", eaBefore)
1342		}
1343		if eaBefore.Operator != "李四" {
1344			t.Fatalf("前置处理人应为退回人李四")
1345		}
1346	
1347		// 即使填了操作人、退回原因、跟踪说明与后续负责人，也不能跳过重新提交。
1348		try := func(act EntryAction, reason, note, follow string) {
1349			t.Helper()
