1351				t.Fatalf("退回未重新提交时 %s 应报 ErrHandoverState，got %v", act, err)
1352			}
1353		}
1354		try(ActionConfirm, "", "", "")
1355		try(ActionConfirm, "硬塞退回原因", "硬塞跟踪说明", "硬塞负责人")
1356		try(ActionTrack, "", "继续跟踪说明", "王五")
1357		try(ActionReturn, "第二次退回原因", "", "")
1358	
1359		got, _ := f.svc.GetHandover(h.ID)
1360		ea := findEntryOf(t, got, idA)
1361		if ea.Status != EntryReturned {
1362			t.Fatalf("失败后状态仍应为退回，got %s", ea.Status)
1363		}
