1365			t.Fatalf("失败处理不应增加退回轮次，got %d", len(ea.Rounds))
1366		}
1367		r := ea.Rounds[0]
1368		if r.Reason != "信息不全，需补充图纸" || r.ReturnOperator != "李四" {
1369			t.Fatalf("上一轮退回原因与退回人不得覆盖：%+v", r)
1370		}
1371		if r.Supplement != "" || r.SupplementOperator != "" || r.ResubmittedAt != nil {
1372			t.Fatalf("失败处理不得写入补充或重新提交信息：%+v", r)
1373		}
1374		if ea.Operator != "李四" || ea.ProcessedAt == nil || !ea.ProcessedAt.Equal(*returnedAt) {
1375			t.Fatalf("上次处理人和时间不得被覆盖：op=%s at=%v want %s %s",
1376				ea.Operator, ea.ProcessedAt, "李四", returnedAt)
1377		}
1378		if ea.FollowOwner != "李四" || ea.TrackingNote != "" {
1379			t.Fatalf("失败处理不得调整后续负责人或留下跟踪说明：%+v", ea)
1380		}
1381	
1382		it, _ := f.svc.GetItem(idA)
1383		if it.CurrentShiftID != a.ID || it.FollowOwner != "李四" {
1384			t.Fatalf("失败处理不得移动事项班次或改负责人：%+v", it)
1385		}
1386		if got.Completed() || got.CompletedAt != nil {
1387			t.Fatalf("交接完成情况不得变化，应仍未完成")
1388		}
1389		eb := findEntryOf(t, got, idB)
1390		if eb.Status != EntryConfirmed {
1391			t.Fatalf("其他事项结果不应受影响：%s", eb.Status)
1392		}
1393	
